-- +goose Up

-- An API is identified by the string access tokens carry as aud.
CREATE TABLE apis (
    identifier text PRIMARY KEY,
    name       text NOT NULL,
    builtin    boolean NOT NULL DEFAULT false,
    created_at timestamptz NOT NULL DEFAULT now()
);

CREATE TABLE applications (
    client_id                 text PRIMARY KEY,
    name                      text NOT NULL,
    type                      text NOT NULL CHECK (type IN ('public', 'confidential')),
    -- SHA-256 of the client secret (high-entropy, generated by us).
    secret_hash               bytea,
    redirect_uris             text[] NOT NULL DEFAULT '{}',
    post_logout_redirect_uris text[] NOT NULL DEFAULT '{}',
    default_api               text REFERENCES apis (identifier),
    -- Idle Session lifetime; NULL means the default (docs/spec/protocol.md#session).
    session_idle_timeout      interval,
    builtin                   boolean NOT NULL DEFAULT false,
    created_at                timestamptz NOT NULL DEFAULT now(),
    CHECK ((type = 'confidential') = (secret_hash IS NOT NULL))
);

