-- go-oidc records. Short-lived rows carry expires_at and are deleted by the
-- hourly cleanup. Grants hold bearer secrets (auth code, refresh token), so the
-- whole record is sealed with the master key and looked up by SHA-256.
CREATE TABLE oidc_grants (
    id                 text PRIMARY KEY,
    auth_code_hash     bytea UNIQUE,
    refresh_token_hash bytea UNIQUE,
    -- NULL: a refresh token without expiry keeps the grant alive.
    expires_at         timestamptz,
    sealed             bytea NOT NULL
);
CREATE INDEX ON oidc_grants (expires_at);

CREATE TABLE oidc_authn_sessions (
    id         text PRIMARY KEY,
    expires_at timestamptz NOT NULL,
    data       jsonb NOT NULL
);
CREATE INDEX ON oidc_authn_sessions (expires_at);

CREATE TABLE oidc_logout_sessions (
    id         text PRIMARY KEY,
    expires_at timestamptz NOT NULL,
    data       jsonb NOT NULL
);
CREATE INDEX ON oidc_logout_sessions (expires_at);

-- RS256 signing keys, PKCS #8 sealed with the master key. The newest signs;
-- the one before it stays in the JWKS so tokens it signed still verify.
CREATE TABLE signing_keys (
    kid        text PRIMARY KEY,
    created_at timestamptz NOT NULL DEFAULT clock_timestamp(),
    sealed     bytea NOT NULL
);
